package run.ikaros.music;
import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.PatchMapping; import org.springframework.web.bind.annotation.PathVariable; import org.springframework.web.bind.annotation.RequestBody; import org.springframework.web.bind.annotation.RequestHeader; import org.springframework.web.bind.annotation.RequestMapping; import org.springframework.web.bind.annotation.RestController; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/music/metadata-candidates") public class MusicMetadataCorrectionController { private final MusicMetadataCorrectionService service; public MusicMetadataCorrectionController(MusicMetadataCorrectionService service){this.service=service;} @PatchMapping("/{candidateId}") public Mono<MusicMetadataCandidateView> update(@RequestHeader("X-Ikaros-Actor-Id") UUID ownerId,@RequestHeader(value="If-Match",required=false) Long expectedVersion,@PathVariable UUID candidateId,@Valid @RequestBody UpdateMusicMetadataCandidateRequest request){return service.update(ownerId,candidateId,request,expectedVersion);} }
